import json, re, statistics, time, urllib.request
import serial
p='/dev/cu.usbserial-1130'
h=serial.Serial(p,115200,timeout=0.1,write_timeout=1)
h.dtr=False; h.rts=False
end=time.monotonic()+135
raw=bytearray()
status_sent=False
while time.monotonic()<end:
    n=h.in_waiting
    if n: raw.extend(h.read(n))
    remaining=end-time.monotonic()
    if not status_sent and remaining < 20:
        h.write(b'status\n'); h.flush(); status_sent=True
    time.sleep(0.05)
if status_sent:
    time.sleep(2)
    n=h.in_waiting
    if n: raw.extend(h.read(n))
h.close()
text=raw.decode(errors='replace')
print('STAGE28E_B_HW_V2_SERIAL_CHARS',len(text))
print(text[-30000:])
markers=[x for x in text.splitlines() if 'stage28e_breadcrumb_restart_selftest action=esp_restart' in x]
crumbs=[x for x in text.splitlines() if 'stage28e_breadcrumb previous_valid=' in x]
heartbeats=[x for x in text.splitlines() if 'heartbeat seq=' in x]
heap_ok=[x for x in text.splitlines() if 'heap_integrity_ok check=' in x]
status=[x for x in text.splitlines() if x.startswith('status ')]
coredump=[x for x in text.splitlines() if 'stage28e_coredump present=' in x]
if len(markers)!=1: raise SystemExit(f'expected exactly one esp_restart selftest marker, got {len(markers)}')
valid=[x for x in crumbs if 'previous_valid=1' in x]
if not valid: raise SystemExit('missing valid RTC breadcrumb after esp_restart')
if 'reset_reason=1' not in valid[-1]: print('STAGE28E_B_HW_V2_NOTE previous breadcrumb reset_reason was not poweron:',valid[-1])
