for token in ['firmware_sha=b43516a2adcd320b3da2b4ee9051e442cceb5c93','outputs=fake-locked','internal_free=','internal_min=','internal_largest=','psram_free=','psram_min=','psram_largest=','boot_id=','reset_reason=']:
    if token not in s: raise SystemExit('missing status token '+token)
for bad in ['heap_integrity_failed','arbiter_counter_regression','Guru Meditation Error','CORRUPT HEAP','Stack canary watchpoint triggered']:
    if bad in text: raise SystemExit('unexpected runtime fault marker: '+bad)
if not coredump or not any('present=0' in x for x in coredump): raise SystemExit('missing clean coredump boot evidence')
vals=[]; outputs=[]
for _ in range(5):
    with urllib.request.urlopen('http://192.168.0.16/rpc/Switch.GetStatus?id=0',timeout=5) as r: d=json.load(r)
    vals.append(float(d.get('apower',0.0))); outputs.append(bool(d.get('output',False))); time.sleep(0.5)
med=statistics.median(vals)
print('STAGE28E_B_HW_V2_RESTART_MARKER',markers[-1])
print('STAGE28E_B_HW_V2_BREADCRUMB',valid[-1])
print('STAGE28E_B_HW_V2_HEARTBEATS',len(heartbeats),'HEAP_OK',len(heap_ok))
print('STAGE28E_B_HW_V2_STATUS',s)
print('STAGE28E_B_HW_V2_SHELLY output_all_on=%d median_apower_w=%.2f samples=%s' % (all(outputs),med,vals))
if not all(outputs): raise SystemExit('Shelly master is not ON')
if not (45.0 <= med <= 80.0): raise SystemExit('unexpected growbox power before restore; expected safe lamp-on region around 61.7W')
